using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Drawing;
using System.Windows.Forms;
internal static class FeatureVerification {
 internal static void Run(string artifacts,bool large){
  Directory.CreateDirectory(artifacts);var lines=new List<string>();Action<string> note=s=>{lines.Add(s);File.WriteAllLines(Path.Combine(artifacts,"features.txt"),lines);};
  var backend=new BaselineCliBackend();RuntimeTelemetry last=null;var decisions=new List<AdaptiveDecision>();backend.TelemetryReceived+=s=>last=s;backend.DecisionReceived+=s=>decisions.Add(s);
  var workloads=new List<string>();
  foreach(string kind in new[]{"Deep","Wide","Mixed","Small Files"}){
   string root=null;
   string dataRoot=Path.Combine(SearchRunner.Root,"target","benchmark-data");
   if(large && Directory.Exists(dataRoot))root=Directory.GetDirectories(dataRoot,kind.Replace(" ","-")+"-*").LastOrDefault(p=>File.Exists(Path.Combine(p,"DATASET_MANIFEST.md")) && File.ReadAllText(Path.Combine(p,"DATASET_MANIFEST.md")).Contains("Files: 20000") && Directory.GetFiles(p,"*.txt",SearchOption.AllDirectories).Length==20000);
   if(root==null)root=DatasetGenerator.Generate(kind,large?20000:100,p=>{},()=>false);workloads.Add(root);
   var expected=new HashSet<string>(Directory.GetFiles(root,"*.txt",SearchOption.AllDirectories),StringComparer.OrdinalIgnoreCase);
   foreach(int method in new[]{2,1,5,3}){var request=new SearchRequest{Folder=root,Pattern="*.txt",Depth=100,Method=method,Threads=4,MaximumWorkers=4};var report=backend.Run(request,p=>{},()=>false);if(!report.Succeeded||!expected.SetEquals(report.Paths))throw new Exception("Workload mismatch: "+kind+" method "+method+": "+report.Error);note("PASS "+kind+" method "+method+" / "+report.Paths.Count+" files / "+report.TotalMilliseconds.ToString("F3")+"ms");}
   if(last==null||last.FilesScanned!=Directory.GetFiles(root,"*",SearchOption.AllDirectories).Length||last.PendingDirectories!=0||last.ActiveWorkers!=0||last.DirectoriesScanned!=Directory.GetDirectories(root,"*",SearchOption.AllDirectories).Length+1||decisions.Count==0)throw new Exception("Telemetry counters inaccurate");note("PASS "+kind+" telemetry: files="+last.FilesScanned+" dirs="+last.DirectoriesScanned+" depth="+last.MaxDepth+" decisions="+decisions.Count);
   var expectedContent=large?new HashSet<string>(expected.Where(p=>Path.GetFileName(p)=="material_019999.txt"),StringComparer.OrdinalIgnoreCase):expected;
   foreach(int method in new[]{2,1,5}){var report=backend.Run(new SearchRequest{Folder=root,Pattern=large?"File 19999":"algorithm",Content=true,Method=method,Depth=100,Threads=4,MaximumWorkers=4},p=>{},()=>false);if(!report.Succeeded||!expectedContent.SetEquals(report.Paths))throw new Exception("Content mismatch "+kind);note("PASS "+kind+" content method "+method+" / "+report.Paths.Count+" matches");}
   if(large){var plan=new BenchmarkPlan{Request=new SearchRequest{Folder=root,Pattern="*099*.txt",Depth=100,MaximumWorkers=8},Runs=3,Warmups=1,Lab=true};plan.Configurations.Add(new RunConfiguration{Method=2,Threads=1});foreach(int n in new[]{1,2,4,8,0})plan.Configurations.Add(new RunConfiguration{Method=1,Threads=n});plan.Configurations.Add(new RunConfiguration{Method=5,Threads=8});plan.Configurations.Add(new RunConfiguration{Method=3,Threads=1});var result=new BenchmarkRunner(backend).Run(plan,p=>{},()=>false,p=>{});ReportExporter.Benchmark(Path.Combine(artifacts,kind.Replace(" ","-")+"-benchmark.csv"),result);foreach(var m in result.Measurements)note(kind+" | "+m.Configuration.Name+" | median="+m.Median.ToString("F3")+"ms min="+m.Minimum.ToString("F3")+" max="+m.Maximum.ToString("F3")+" matches="+result.Matches.Paths.Count);}
  }
  File.WriteAllLines(Path.Combine(artifacts,"workloads.txt"),workloads);
  string academic=@"D:\RAFS_Demo\01_Academic_Search";
  if(Directory.Exists(academic)){var expectedPdf=new HashSet<string>(Directory.GetFiles(academic,"*.pdf",SearchOption.AllDirectories),StringComparer.OrdinalIgnoreCase);foreach(int method in new[]{1,2,3,5}){var report=backend.Run(new SearchRequest{Folder=academic,Pattern="*.pdf",Method=method,Depth=12},p=>{},()=>false);if(!report.Succeeded||!expectedPdf.SetEquals(report.Paths))throw new Exception("Academic regression: method "+method);note("PASS academic method "+method+" / "+report.Paths.Count+" identical PDFs");}var index=backend.Run(new SearchRequest{Folder=academic,Pattern="*.pdf",Method=4,Depth=12},p=>{},()=>false);note("Index query: succeeded="+index.Succeeded+", indexed PDFs="+index.Paths.Count+", live PDFs="+expectedPdf.Count);if(index.Succeeded && !expectedPdf.SetEquals(index.Paths)){var mismatch=new BenchmarkPlan{Request=new SearchRequest{Folder=academic,Pattern="*.pdf",Depth=12},Runs=1,Warmups=0};mismatch.Configurations.Add(new RunConfiguration{Method=2,Threads=1});mismatch.Configurations.Add(new RunConfiguration{Method=4,Threads=1});try{new BenchmarkRunner(backend).Run(mismatch,p=>{},()=>false,p=>{});throw new Exception("Index mismatch was hidden");}catch(InvalidOperationException e){if(!e.Message.StartsWith("RESULT MISMATCH"))throw;note("PASS incomplete index mismatch is reported and suppresses graph");}}}
  bool cancelled=false;try{backend.Run(new SearchRequest{Folder=workloads[0],Pattern="*",Method=5,Depth=100},p=>{if(p!=null){cancelled=true;SearchRunner.TryStop(p);}},()=>cancelled);throw new Exception("Adaptive cancellation ignored");}catch(OperationCanceledException){note("PASS adaptive cancellation");}
  string fixture=Path.Combine(artifacts,"quoted ' Unicode α [folder] "+Guid.NewGuid().ToString("N").Substring(0,8));Directory.CreateDirectory(fixture);File.WriteAllText(Path.Combine(fixture,"lecture α.txt"),"memory process");
  foreach(int method in new[]{1,2,3,5}){var report=backend.Run(new SearchRequest{Folder=fixture,Pattern="*.txt",Method=method},p=>{},()=>false);if(!report.Succeeded||report.Paths.Count!=1)throw new Exception("Quoted Unicode path failed");}
  foreach(int method in new[]{1,2,3,5}){var report=backend.Run(new SearchRequest{Folder=fixture,Pattern="lecture",Method=method},p=>{},()=>false);if(!report.Succeeded||report.Paths.Count!=1)throw new Exception("Plain substring match failed");}
  File.WriteAllText(Path.Combine(fixture,"copy α.txt"),"memory process");var dup=backend.Run(new SearchRequest{Folder=fixture,Pattern="*.txt",DuplicateMode="content"},p=>{},()=>false);if(!dup.Succeeded||dup.Paths.Count!=2)throw new Exception("Duplicate GUI backend failed");note("PASS safe quoted/Unicode arguments and duplicate-content result paths");
  File.WriteAllText(Path.Combine(fixture,"flag-marker.txt"),"literal -m 5 marker");foreach(int method in new[]{2,5}){var report=backend.Run(new SearchRequest{Folder=fixture,Pattern="literal -m 5 marker",Content=true,Method=method},p=>{},()=>false);if(!report.Succeeded||report.Paths.Count!=1)throw new Exception("Method-looking content was rewritten");}note("PASS adaptive arguments preserve literal method-looking content");
  string largePreview=Path.Combine(fixture,"large-preview.txt");using(var writer=new StreamWriter(largePreview)){for(int i=0;i<100000;i++)writer.WriteLine("preview memory process algorithm row "+i);}
  var preview=backend.Run(new SearchRequest{Folder=fixture,Pattern="preview memory",Content=true,Method=2},p=>{},()=>false);if(!preview.Succeeded||preview.Paths.Count!=1||!preview.Output.Contains("preview limited")||preview.Output.Length>2*1024*1024+200)throw new Exception("Raw preview memory bound failed");note("PASS large content preview is bounded while result paths remain complete");
  using(var app=new AppShell(backend,new SettingsService(Path.Combine(artifacts,"settings.xml")))){app.Show();Application.DoEvents();var request=new SearchRequest{Folder=workloads[2],Pattern="*.txt",Depth=100,Method=5,MaximumWorkers=4};app.Search.Options.SetRequest(request);app.Session.StartSearch(request);Wait(app.Session);if(app.Session.Telemetry==null||app.Session.Decisions.Count==0)throw new Exception("Live UI telemetry missing");app.ShowPage("Live Monitor");Capture(app,artifacts,"adaptive-monitor");
   var plan=new BenchmarkPlan{Request=request,Runs=2,Warmups=1};plan.Configurations.Add(new RunConfiguration{Method=2,Threads=1});plan.Configurations.Add(new RunConfiguration{Method=5,Threads=4});app.Session.StartBenchmark(plan);Wait(app.Session);app.ShowPage("Compare");Capture(app,artifacts,"adaptive-compare");plan.Lab=true;app.Session.StartBenchmark(plan);Wait(app.Session);app.ShowPage("Benchmark Lab");Capture(app,artifacts,"adaptive-benchmark");app.Session.StartDuplicates(new SearchRequest{Folder=fixture,Pattern="*.txt",DuplicateMode="content"});Wait(app.Session);app.ShowPage("Duplicates");Capture(app,artifacts,"duplicates");app.Close();}
  note("PASS adaptive session, live metrics, comparison, benchmark, duplicate page and native rendering");
  Theme.SetDark(true);using(var darkApp=new AppShell(new BaselineCliBackend(),new SettingsService(Path.Combine(artifacts,"dark-settings.xml")))){darkApp.Show();Application.DoEvents();foreach(string page in new[]{"Search","Live Monitor","Compare","Benchmark Lab","Duplicates","Settings"}){darkApp.ShowPage(page);Capture(darkApp,artifacts,"dark-"+page.Replace(" ","-"));}darkApp.Close();}Theme.SetDark(false);note("PASS dark theme renders all six pages");
 }
 private static void Wait(SearchSession session){var t=System.Diagnostics.Stopwatch.StartNew();while(session.IsBusy&&t.Elapsed.TotalSeconds<120){Application.DoEvents();System.Threading.Thread.Sleep(10);}Application.DoEvents();if(session.State!=SessionState.Completed)throw new Exception(session.Message);}
 private static void Capture(AppShell app,string artifacts,string name){if(app.Session.Request!=null&&(app.CurrentPage=="Compare"||app.CurrentPage=="Benchmark Lab"||app.CurrentPage=="Duplicates")){var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;var pages=(Dictionary<string,AppPage>)typeof(AppShell).GetField("pages",flags).GetValue(app);var page=pages[app.CurrentPage];var request=app.Session.Request.Copy();request.Method=1;((SearchOptionsPanel)page.GetType().GetField("options",flags).GetValue(page)).SetRequest(request);if(app.CurrentPage!="Duplicates"){((NumericUpDown)page.GetType().GetField("depth",flags).GetValue(page)).Value=request.Depth;((NumericUpDown)page.GetType().GetField("runs",flags).GetValue(page)).Value=2;if(app.CurrentPage=="Compare"){foreach(var item in new[]{new{Field="configA",Index=1},new{Field="configB",Index=4}}){var picker=page.GetType().GetField(item.Field,flags).GetValue(page);((ComboBox)picker.GetType().GetField("method",flags).GetValue(picker)).SelectedIndex=item.Index;((NumericUpDown)picker.GetType().GetField("threads",flags).GetValue(picker)).Value=4;}}else{((CheckBox)page.GetType().GetField("method1",flags).GetValue(page)).Checked=false;}}}app.Refresh();Application.DoEvents();using(var bitmap=new Bitmap(app.Width,app.Height)){app.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(Path.Combine(artifacts,name+".png"));}}
}
